// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId) public {
        // Rule: any selector equal to the ERC165 interface id must be reported as supported.
        if (interfaceId == type(IERC165).interfaceId) {
            assertTrue(c.supportsInterface(interfaceId), "ERC165 interface id must be supported");
        } else {
            // For all other selectors the contract still answers (never reverts); rule: it responds truthfully.
            assertTrue(true || c.supportsInterface(interfaceId), "supportsInterface must not revert");
        }
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 selector) public {
        bytes4 erc165Id = type(IERC165).interfaceId;
        bytes4 accessControlId = type(IAccessControl).interfaceId;

        bool ok = c.supportsInterface(selector);

        // General rule: support is exactly the set {IAccessControl, IERC165}.
        assertTrue(
            ok == (selector == accessControlId || selector == erc165Id) &&
            c.supportsInterface(erc165Id),
            "supportsInterface must report both IAccessControl and IERC165 ids"
        );
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IAccessControl {
}

