pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {IAccessControl, IERC165} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 selector) public {
        // Rule: for ANY selector, c.supportsInterface(sel) is true if and only if
        // sel is the IAccessControl interface id or the IERC165 interface id,
        // and the call never reverts for any selector.
        bool expected = (selector == type(IAccessControl).interfaceId) ||
                        (selector == type(IERC165).interfaceId);
        bool reported = c.supportsInterface(selector);
        assertTrue(reported == expected);
    }
}

